import { useEffect, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  DEFAULT_SORT,
  EYEBROW,
  SEARCH_PLACEHOLDER,
  SUBTITLE,
  TITLE,
  fetchSentOffers,
  filterSentOffers,
  resultCountLabel,
  sortSentOffers,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import { SentOffersTable } from './SentOffersTable';
import styles from './SentOffers.module.css';

/**
 * VND-01 · Mis Ofertas (vista del vendedor).
 *
 * La pantalla posee TODO el estado: lista, carga, error, texto de búsqueda y
 * ordenación. El orden de operaciones es FILTRAR y luego ORDENAR (§4 · §5.4);
 * la tabla recibe las filas ya filtradas y ya ordenadas y no vuelve a tocarlas.
 *
 * `onOpenThread` es opcional para no romper el wiring del shell si todavía no
 * navega a MSG-02; el botón de la fila sigue viviendo en la tabla.
 */
export function SentOffers({
  profile,
  onOpenThread,
}: {
  profile: MemberProfile;
  onOpenThread?: (threadId: string) => void;
}) {
  const [offers, setOffers] = useState<SentOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<{ column: SortColumn; direction: SortDirection }>(DEFAULT_SORT);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchSentOffers(profile.orgId)
      .then((data) => {
        if (!cancelled) setOffers(data);
      })
      .catch((err: unknown) => {
        if (!cancelled) setError(err);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId]);

  const filtered = filterSentOffers(offers, query);
  const sorted = sortSentOffers(filtered, sort.column, sort.direction);
  const hasQuery = query.trim().length > 0;

  const handleSort = (column: SortColumn) => {
    setSort((prev) =>
      prev.column === column
        ? { column, direction: prev.direction === 'asc' ? 'desc' : 'asc' }
        : { column, direction: 'asc' },
    );
  };

  return (
    <div className={styles.body} data-testid="selling-body" aria-busy={loading ? 'true' : 'false'}>
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      <div className={styles.searchBar}>
        <div className={styles.searchWrap}>
          <input
            type="text"
            className={styles.searchInput}
            placeholder={SEARCH_PLACEHOLDER}
            aria-label={SEARCH_PLACEHOLDER}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          {hasQuery && (
            <button
              type="button"
              className={styles.clearButton}
              aria-label="Limpiar búsqueda"
              onClick={() => setQuery('')}
            >
              ×
            </button>
          )}
        </div>
        <span className={styles.resultCount}>{resultCountLabel(sorted.length)}</span>
      </div>

      {error !== null ? (
        <div role="alert" className={styles.error}>
          {errorMessage(error)}
        </div>
      ) : loading ? (
        <p className={styles.loading}>Cargando ofertas…</p>
      ) : (
        <SentOffersTable
          offers={sorted}
          sort={sort}
          onSort={handleSort}
          onOpenThread={(threadId) => onOpenThread?.(threadId)}
          hasQuery={hasQuery}
        />
      )}
    </div>
  );
}

.tableOuter {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: auto;
  max-height: calc(100vh - 270px);
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  padding: 9px 14px;
  text-align: left;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bw-text-secondary);
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 1;
  user-select: none;
}

.sortButton {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: none;
  border: none;
  padding: 0;
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  text-transform: uppercase;
  color: inherit;
  cursor: pointer;
}

.sortButton:hover {
  color: var(--bw-deep-steel);
}

.sortIcon {
  font-style: normal;
  font-size: 10px;
  line-height: 1;
  color: var(--bw-text-secondary);
  opacity: 0.45;
}

.sortAsc .sortIcon,
.sortDesc .sortIcon {
  color: var(--bw-calibration-blue);
  opacity: 1;
}

.td {
  padding: 10px 14px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
  white-space: nowrap;
}

.table tbody tr:last-child td {
  border-bottom: none;
}

.table tbody tr:hover td {
  background: var(--bw-row-hover-tint);
}

.partNumber {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.brand {
  display: block;
  margin-top: 1px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
}

.org {
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-ink-steel);
}

.badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  letter-spacing: 0.05em;
}

.badgePending {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.badgeAccepted {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.badgeRejected {
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  border: 1px solid var(--bw-badge-danger-border);
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.date {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-text-secondary);
}

.actionButton {
  height: 26px;
  padding: 0 10px;
  border-radius: 4px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.12s, border-color 0.12s, color 0.12s, opacity 0.12s;
}

.actionPrimary {
  background: var(--bw-calibration-blue);
  /* No hay token de blanco puro en el sistema (§1.1): el texto sobre la acción
     primaria usa el neutro claro más próximo para mantener el contraste. */
  color: var(--bw-cold-white);
  border: none;
}

.actionPrimary:hover {
  opacity: 0.87;
}

.actionGhost {
  background: none;
  color: var(--bw-text-secondary);
  border: 1px solid var(--bw-line-steel-strong);
}

.actionGhost:hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.emptyCell {
  text-align: center;
  padding: 48px 20px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  color: var(--bw-input-placeholder);
}

import type { OfferState } from '../../lib/offers';
import {
  EMPTY_NO_MATCHES,
  EMPTY_NO_OFFERS,
  rowActionLabel,
  sentAtLabel,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import styles from './SentOffersTable.module.css';

interface Props {
  offers: SentOffer[];
  sort: { column: SortColumn; direction: SortDirection };
  onSort: (column: SortColumn) => void;
  onOpenThread: (threadId: string) => void;
  hasQuery: boolean;
}

/**
 * Las cinco columnas de la §5.1, en el orden fijo e inamovible.
 * Las cuatro primeras son ordenables; `Acciones` no lo es (§5.4).
 */
const COLUMNS: { key?: SortColumn; label: string; sortable: boolean }[] = [
  { label: 'Referencia', key: 'referencia', sortable: true },
  { label: 'Organización', key: 'organizacion', sortable: true },
  { label: 'Estado', key: 'estado', sortable: true },
  { label: 'Fecha', key: 'fecha', sortable: true },
  { label: 'Acciones', sortable: false },
];

/**
 * Tono del badge para cada estado. Los cuatro literales del CHECK de 0003:
 * 'Pendiente', 'Aceptada', 'Rechazada' y 'Superada por contraoferta' — este
 * último no está en la §5.2 del mock, pero existe en el esquema y puede
 * aparecer de verdad (MSG-02 ya lo pinta).
 */
const STATE_CLASS: Record<OfferState, string> = {
  'Pendiente': styles.badgePending,
  'Aceptada': styles.badgeAccepted,
  'Rechazada': styles.badgeRejected,
  'Superada por contraoferta': styles.badgeNeutral,
};

/**
 * Tabla de ofertas enviadas de VND-01.
 *
 * Presentacional: recibe las filas ya filtradas y ya ordenadas y no vuelve a
 * tocarlas. Los dos estados vacíos viven aquí, dentro de la tabla, porque
 * "no hay filas" es un estado de la lista y no de la pantalla.
 */
export function SentOffersTable({ offers, sort, onSort, onOpenThread, hasQuery }: Props) {
  return (
    <div className={styles.tableOuter}>
      <table className={styles.table}>
        <thead>
          <tr>
            {COLUMNS.map((col) => {
              const sortKey = col.sortable ? col.key : undefined;
              const active = sortKey !== undefined && sort.column === sortKey ? sort : null;
              const cls = [styles.th];
              if (sortKey !== undefined) {
                cls.push(styles.sortable);
                if (active !== null) {
                  cls.push(active.direction === 'asc' ? styles.sortAsc : styles.sortDesc);
                }
              }
              const ariaSort =
                active !== null
                  ? active.direction === 'asc'
                    ? 'ascending'
                    : 'descending'
                  : sortKey !== undefined
                    ? 'none'
                    : undefined;
              return (
                <th key={col.label} scope="col" aria-sort={ariaSort} className={cls.join(' ')}>
                  {/*
                   * La cabecera ordenable es un BOTÓN dentro del `<th>`, no un
                   * `onClick` sobre la celda: con teclado no existe un div con
                   * onClick — no recibe foco, no responde a Enter y ningún
                   * lector de pantalla lo anuncia como accionable. El sentido se
                   * declara en `aria-sort` del `<th>`; la flecha es un adorno
                   * `aria-hidden`.
                   */}
                  {sortKey !== undefined ? (
                    <button type="button" className={styles.sortButton} onClick={() => onSort(sortKey)}>
                      {col.label}
                      <span className={styles.sortIcon} aria-hidden="true">
                        {active !== null ? (active.direction === 'asc' ? '↑' : '↓') : '↕'}
                      </span>
                    </button>
                  ) : (
                    col.label
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {offers.length === 0 ? (
            <tr>
              <td colSpan={COLUMNS.length} className={`${styles.td} ${styles.emptyCell}`}>
                {hasQuery ? EMPTY_NO_MATCHES : EMPTY_NO_OFFERS}
              </td>
            </tr>
          ) : (
            offers.map((offer) => (
              <tr key={offer.id} data-testid="sent-offer-row" data-offer-id={offer.id}>
                <td className={styles.td}>
                  <span className={styles.partNumber}>{offer.partNumber ?? '—'}</span>
                  {offer.brand !== null && offer.brand !== '' && (
                    <span className={styles.brand}>{offer.brand}</span>
                  )}
                </td>
                <td className={styles.td}>
                  <span className={styles.org}>{offer.counterpartyName}</span>
                </td>
                <td className={styles.td}>
                  <span className={`${styles.badge} ${STATE_CLASS[offer.state]}`}>{offer.state}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.date}>{sentAtLabel(offer.createdAt)}</span>
                </td>
                <td className={styles.td}>
                  <button
                    type="button"
                    className={`${styles.actionButton} ${offer.state === 'Aceptada' ? styles.actionPrimary : styles.actionGhost}`}
                    onClick={() => onOpenThread(offer.threadId)}
                  >
                    {rowActionLabel(offer.state)}
                  </button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
